CREATE POLICY "Anyone can read published results files" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'published-results');
CREATE POLICY "Admins upload published results files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'published-results' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins update published results files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'published-results' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins delete published results files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'published-results' AND public.has_role(auth.uid(), 'admin'));